1	package world
2	
3	// World 是一个本地世界实例。它持有当前完整状态，零值不可用，
4	// 必须通过 NewWorld 建立。
5	type World struct {
6		state State
7	}
8	
9	// NewWorld 用初始数据建立世界。时间片从零开始；初始数据违反规则时
10	// 返回 *RuleError，且不会产生可用世界。
11	func NewWorld(data InitialData) (*World, error) {
12		if err := validateInitialData(data); err != nil {
13			return nil, err
14		}
15		return &World{state: State{
16			Seed:       data.Seed,
17			Rules:      cloneRules(data.Rules),
18			Time:       0,
19			Characters: cloneCharacters(data.Characters),
20		}}, nil
21	}
22	
23	// WorldFromState 用一份完整状态（典型地来自存档记录）重建世界，
24	// 保留其中的时间片。与 NewWorld 不同，它用于“读档后继续”：状态必须
25	// 自洽且时间片非负，否则返回 *RuleError。入参会被深拷贝。
26	func WorldFromState(st State) (*World, error) {
27		if st.Time < 0 {
28			return nil, ruleErrorf("时间片不能为负: %d", st.Time)
29		}
30		if err := validateInitialData(InitialData{
31			Seed:       st.Seed,
32			Rules:      st.Rules,
33			Characters: st.Characters,
34		}); err != nil {
35			return nil, err
36		}
37		return &World{state: cloneState(st)}, nil
38	}
39	
40	// Snapshot 返回当前世界状态的深拷贝，修改返回值不会影响世界。
41	func (w *World) Snapshot() State {
42		return cloneState(w.state)
43	}
44	
45	// Apply 在一次原子提交中应用若干移动、物品数量变化和时间推进。
46	//
47	// 提交中的任意一项不合法（角色/物品不存在、移动不沿允许的连通关系、
48	// 物品数量变负、总量超过携带上限、时间倒退等）都会使整次提交失败，
49	// 世界保持提交前状态。成功时返回提交后的状态深拷贝。
50	func (w *World) Apply(c Commit) (State, error) {
51		next, err := w.state.apply(c)
52		if err != nil {
53			return State{}, err
54		}
55		w.state = next
56		return cloneState(w.state), nil
57	}
58	
59	func (s State) apply(c Commit) (State, error) {
60		if c.Time < s.Time {
61			return State{}, ruleErrorf("时间不能倒退: 当前 %d, 提交目标 %d", s.Time, c.Time)
62		}
63	
64		next := cloneState(s)
65	
66		locSet := make(map[string]struct{}, len(next.Rules.Locations))
67		for _, l := range next.Rules.Locations {
68			locSet[l] = struct{}{}
69		}
70		kindSet := make(map[string]struct{}, len(next.Rules.ItemKinds))
71		for _, k := range next.Rules.ItemKinds {
72			kindSet[k] = struct{}{}
73		}
74		chars := make(map[string]*Character, len(next.Characters))
75		for i := range next.Characters {
76			chars[next.Characters[i].ID] = &next.Characters[i]
77		}
78	
79		// 移动：逐条应用，每条都必须沿规则允许的连通关系。
80		for _, m := range c.Moves {
81			ch, ok := chars[m.Character]
82			if !ok {
83				return State{}, ruleErrorf("移动引用了不存在的角色: %q", m.Character)
84			}
85			if _, ok := locSet[m.To]; !ok {
86				return State{}, ruleErrorf("角色 %q 移动到不存在的地点: %q", m.Character, m.To)
87			}
88			if !next.Rules.adjacent(ch.Location, m.To) {
89				return State{}, ruleErrorf("角色 %q 不能从 %q 移动到 %q：没有允许的连通关系",
90					m.Character, ch.Location, m.To)
91			}
92			ch.Location = m.To
93		}
94	
95		// 物品数量变化：先在工作副本上累计，最后统一校验非负与上限。
96		for _, ic := range c.ItemChanges {
97			ch, ok := chars[ic.Character]
98			if !ok {
99				return State{}, ruleErrorf("物品变化引用了不存在的角色: %q", ic.Character)
100			}
101			if _, ok := kindSet[ic.Item]; !ok {
102				return State{}, ruleErrorf("角色 %q 的物品变化引用了规则不允许的物品: %q",
103					ic.Character, ic.Item)
104			}
105			idx := -1
106			for i := range ch.Items {
107				if ch.Items[i].Item == ic.Item {
108					idx = i
109					break
110				}
111			}
112			if idx == -1 {
113				ch.Items = append(ch.Items, CharacterItem{Item: ic.Item, Count: ic.Delta})
114			} else {
115				ch.Items[idx].Count += ic.Delta
116			}
117		}
118		for _, ch := range next.Characters {
119			total := 0
120			for _, it := range ch.Items {
121				if it.Count < 0 {
122					return State{}, ruleErrorf("角色 %q 的物品 %q 数量不能为负: %d",
123						ch.ID, it.Item, it.Count)
124				}
125				total += it.Count
126			}
127			if limit, ok := next.Rules.CarryLimits[ch.ID]; ok && total > limit {
128				return State{}, ruleErrorf("角色 %q 携带总量 %d 超过上限 %d", ch.ID, total, limit)
129			}
130		}
131	
132		next.Time = c.Time
133		return next, nil
134	}
