13	// 物品种类，保留全部旧内容并提高上限，因此原样承接当前状态没有阻碍。
14	func v2Rules() Rules {
15		return Rules{
16			Version:   "v2",
17			Locations: []string{"hall", "yard", "cave", "tower"},
18			Edges: []Edge{
19				{From: "hall", To: "yard"},
