28	// saveBase 保存一个基础世界并返回槽名与首条记录元信息。
29	func saveBase(t *testing.T, a *Archive, slot string) RecordInfo {
30		t.Helper()
31		w := baseWorld(t)
32		info, err := a.Save(slot, w)
