39	func TestCheckUpgradeCompatible(t *testing.T) {
40		a, _ := newTestArchive(t)
41		info := saveBase(t, a, "s")
42	
43		check, err := a.CheckUpgrade("s", []string{"v1"}, v2Rules())
44		if err != nil {
45			t.Fatalf("CheckUpgrade: %v", err)
46		}
47		if !check.Compatible {
48			t.Fatalf("只增不减的规则应当兼容，得到阻碍: %+v", check.Blockers)
49		}
50		if check.RecordID != info.ID {
51			t.Fatalf("检查的记录标识应为 %s，得到 %s", info.ID, check.RecordID)
52		}
53		if check.OldVersion != "v1" || check.TargetVersion != "v2" {
54			t.Fatalf("版本信息错误: %+v", check)
55		}
56		if len(check.Blockers) != 0 {
57			t.Fatalf("兼容时不应有阻碍，得到 %+v", check.Blockers)
58		}
59	}
