61	func TestCheckUpgradeBlockers(t *testing.T) {
62		a, _ := newTestArchive(t)
63		saveBase(t, a, "s")
64	
65		// 目标规则：删除 hero 所在的 hall、移除 hero 持有的 gold、把 hero 上限
66		// 降到 0。三类阻碍应一次全部返回。
67		target := Rules{
68			Version:     "v2",
69			Locations:   []string{"yard", "cave"},
70			Edges:       []Edge{{From: "yard", To: "cave"}},
71			ItemKinds:   []string{"key"},
72			CarryLimits: map[string]int{"hero": 0, "mage": 5},
73		}
74		check, err := a.CheckUpgrade("s", []string{"v1"}, target)
75		if err != nil {
76			t.Fatalf("CheckUpgrade: %v", err)
77		}
78		if check.Compatible {
79			t.Fatal("存在阻碍时不应兼容")
80		}
81		want := []Blocker{
82			{Character: "hero", Kind: BlockerLocation, Location: "hall"},
83			{Character: "hero", Kind: BlockerItem, Item: "gold"},
84			{Character: "hero", Kind: BlockerLimit, Total: 1, Limit: 0},
85		}
86		if len(check.Blockers) != len(want) {
87			t.Fatalf("期望 %d 条阻碍，得到 %d: %+v", len(want), len(check.Blockers), check.Blockers)
88		}
89		for i := range want {
90			if check.Blockers[i] != want[i] {
91				t.Fatalf("第 %d 条阻碍应为 %+v，得到 %+v", i, want[i], check.Blockers[i])
92			}
93		}
94	}
