168	func TestCheckUpgradeBlockersSorted(t *testing.T) {
169		a, _ := newTestArchive(t)
170		// 故意按与标识不同的顺序插入角色，验证阻碍按角色标识排序。
171		w, err := NewWorld(InitialData{
172			Seed:  1,
173			Rules: baseRules(),
174			Characters: []Character{
175				{ID: "zara", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
176				{ID: "anna", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
177				{ID: "mike", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
178			},
179		})
180		if err != nil {
181			t.Fatal(err)
182		}
183		if _, err := a.Save("s", w); err != nil {
184			t.Fatal(err)
185		}
186		// 移除 hall 地点与 gold 种类，并把三人上限都降到 0。
187		target := Rules{
188			Version:     "v2",
189			Locations:   []string{"yard"},
190			ItemKinds:   []string{"key"},
191			CarryLimits: map[string]int{"zara": 0, "anna": 0, "mike": 0},
192		}
193		check, err := a.CheckUpgrade("s", []string{"v1"}, target)
194		if err != nil {
195			t.Fatalf("CheckUpgrade: %v", err)
196		}
197		// 期望顺序：anna(location, item, limit)、mike(...)、zara(...)。
198		wantOrder := []string{"anna", "anna", "anna", "mike", "mike", "mike", "zara", "zara", "zara"}
199		if len(check.Blockers) != len(wantOrder) {
200			t.Fatalf("期望 %d 条阻碍，得到 %d: %+v", len(wantOrder), len(check.Blockers), check.Blockers)
