207		// 重复检查输出顺序一致。
208		check2, err := a.CheckUpgrade("s", []string{"v1"}, target)
209		if err != nil {
210			t.Fatal(err)
211		}
212		for i := range check.Blockers {
213			if check.Blockers[i] != check2.Blockers[i] {
214				t.Fatalf("重复检查输出顺序不一致: %+v vs %+v", check.Blockers, check2.Blockers)
215			}
216		}
217	}
