243	func TestCheckUpgradeCorruptSource(t *testing.T) {
244		a, dir := newTestArchive(t)
245		info := saveBase(t, a, "s")
246		// 篡改最新记录的校验和。
247		path := recordPath(dir, info.ID)
248		raw, err := os.ReadFile(path)
249		if err != nil {
250			t.Fatal(err)
251		}
252		s := string(raw)
253		i := strings.Index(s, `"checksum": "`)
254		if i < 0 {
255			t.Fatal("找不到 checksum 字段")
256		}
257		start := i + len(`"checksum": "`)
258		end := start + 64
259		s = s[:start] + strings.Repeat("0", 64) + s[end:]
260		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
261			t.Fatal(err)
262		}
263		_, err = a.CheckUpgrade("s", []string{"v1"}, v2Rules())
264		var ce *CorruptError
265		if !errors.As(err, &ce) {
266			t.Fatalf("来源损坏应返回 *CorruptError，得到 %T: %v", err, err)
267		}
