499	func TestUpgradeConcurrent(t *testing.T) {
500		a, dir := newTestArchive(t)
501		info := saveBase(t, a, "s")
502	
503		const n = 8
504		var wg sync.WaitGroup
505		var mu sync.Mutex
506		wins, conflicts := 0, 0
507		errs := make([]error, 0)
508		for i := 0; i < n; i++ {
509			wg.Add(1)
510			go func() {
511				defer wg.Done()
512				// 每个 goroutine 使用独立的 Archive 实例（独立 flock 句柄）。
513				ga, err := Open(dir)
514				if err != nil {
515					mu.Lock()
516					errs = append(errs, err)
517					mu.Unlock()
518					return
519				}
520				_, uerr := ga.Upgrade("s", []string{"v1"}, v2Rules(), info.ID)
521				mu.Lock()
522				defer mu.Unlock()
523				switch {
524				case uerr == nil:
525					wins++
526				case isConflict(uerr):
527					conflicts++
528				default:
529					errs = append(errs, uerr)
530				}
531			}()
532		}
533		wg.Wait()
534		if len(errs) != 0 {
535			t.Fatalf("并发升级出现非冲突错误: %v", errs)
536		}
537		if wins != 1 || conflicts != n-1 {
538			t.Fatalf("期望恰好 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
539		}
540		// 最终槽指向升级后的完整记录。
541		a2, _ := Open(dir)
542		rec, err := a2.Latest("s", []string{"v1", "v2"})
543		if err != nil {
544			t.Fatalf("并发升级后最新记录应完好: %v", err)
545		}
546		if rec.State.Rules.Version != "v2" {
547			t.Fatal("胜出记录应使用目标规则")
548		}
549	}
