package world

import (
	"errors"
	"fmt"
	"os"
	"strings"
	"sync"
	"testing"
)

// v2Rules 是在 v1 基础上“只增不减”的目标规则：新增地点、连通关系和
// 物品种类，保留全部旧内容并提高上限，因此原样承接当前状态没有阻碍。
func v2Rules() Rules {
	return Rules{
		Version:   "v2",
		Locations: []string{"hall", "yard", "cave", "tower"},
		Edges: []Edge{
			{From: "hall", To: "yard"},
