func TestMigrateReopenContinueAndNoAutoConvert(t *testing.T) {
	a, dir := newTestArchive(t)
	info := saveBase(t, a, "s")
	if _, err := a.Migrate("s", []string{"v1"}, renamedV2Rules(), renameMapping(), info.ID); err != nil {
