1	package world
2	
3	import (
4		"fmt"
5		"math"
6	)
7	
8	// NameRename 表示一条旧名称到新名称的显式对应关系。
9	type NameRename struct {
10		// From 是来源记录旧规则中使用的名称（地点或物品种类）。
11		From string
12		// To 是目标规则中使用的名称。
13		To string
14	}
15	
16	// NameMapping 是一次显式迁移使用的名称对应关系：地点改名与物品改名。
17	//
18	// 对应关系按切片给出的次序解释与报错。未出现在对应关系中的名称保持原样；
19	// 每条对应关系只作用于来源状态中的原始名称一次，不会沿对应关系连续替换，
20	// 因此互换名称（A->B、B->A）也有确定结果。
21	type NameMapping struct {
22		// Locations 是旧地点到新地点的对应关系。
23		Locations []NameRename
24		// Items 是旧物品种类到新物品种类的对应关系。
25		Items []NameRename
26	}
27	
28	// MigrationPreview 是一次显式迁移预览的结果。
29	type MigrationPreview struct {
30		// RecordID 是所依据的来源记录标识（槽当前最新记录）。
31		RecordID RecordID
32		// OldVersion 是来源记录的规则版本。
33		OldVersion string
34		// TargetVersion 是目标规则版本。
35		TargetVersion string
36		// State 是按目标规则与对应关系转换后的完整世界状态（深拷贝，
37		// 修改不影响存档，也不会被正式迁移采信）。
38		State State
39		// Committable 表示转换后状态是否可提交：没有缺失地点、不被允许的
40		// 物品或超过目标携带上限等阻碍。
41		Committable bool
42		// Blockers 是转换后仍存在的全部阻碍，排序规则与升级检查一致，
43		// 重复预览输出顺序一致。
44		Blockers []Blocker
45	}
46	
47	// MigrationResult 是正式迁移的返回结果。
48	type MigrationResult struct {
49		// Preview 是对当前来源记录重新读取并计算得到的预览结果。
50		Preview MigrationPreview
51		// Record 是成功时新记录的元信息；被拒绝时为零值。
52		Record RecordInfo
53	}
54	
55	// validateNameMappingLocked 校验对应关系本身：来源名称必须存在于旧规则、
56	// 目标名称必须存在于新规则；即使暂时没有角色使用也要检查。空名称必然
57	// 通不过存在性检查；同一类别内来源重复也按规则错误拒绝。
58	func validateNameMapping(m NameMapping, old, target Rules) error {
59		oldLoc := make(map[string]struct{}, len(old.Locations))
60		for _, l := range old.Locations {
61			oldLoc[l] = struct{}{}
62		}
63		newLoc := make(map[string]struct{}, len(target.Locations))
64		for _, l := range target.Locations {
65			newLoc[l] = struct{}{}
66		}
67		oldKind := make(map[string]struct{}, len(old.ItemKinds))
68		for _, k := range old.ItemKinds {
69			oldKind[k] = struct{}{}
70		}
71		newKind := make(map[string]struct{}, len(target.ItemKinds))
72		for _, k := range target.ItemKinds {
73			newKind[k] = struct{}{}
74		}
75		seenLoc := make(map[string]struct{}, len(m.Locations))
76		for i, r := range m.Locations {
77			if _, ok := oldLoc[r.From]; !ok {
78				return ruleErrorf("地点对应关系 %d 的来源 %q 不存在于旧规则", i, r.From)
79			}
80			if _, ok := newLoc[r.To]; !ok {
81				return ruleErrorf("地点对应关系 %d 的目标 %q 不存在于新规则", i, r.To)
82			}
83			if _, dup := seenLoc[r.From]; dup {
84				return ruleErrorf("地点对应关系的来源重复: %q", r.From)
85			}
86			seenLoc[r.From] = struct{}{}
87		}
88		seenKind := make(map[string]struct{}, len(m.Items))
89		for i, r := range m.Items {
90			if _, ok := oldKind[r.From]; !ok {
91				return ruleErrorf("物品对应关系 %d 的来源 %q 不存在于旧规则", i, r.From)
92			}
93			if _, ok := newKind[r.To]; !ok {
94				return ruleErrorf("物品对应关系 %d 的目标 %q 不存在于新规则", i, r.To)
95			}
96			if _, dup := seenKind[r.From]; dup {
97				return ruleErrorf("物品对应关系的来源重复: %q", r.From)
98			}
99			seenKind[r.From] = struct{}{}
100		}
101		return nil
102	}
103	
104	// addSafe 在整数类型范围内求和，超出范围时返回错误而不是回绕。
105	func addSafe(a, b int) (int, error) {
106		if b > 0 && a > math.MaxInt-b {
107			return 0, ruleErrorf("物品数量合并后超出整数范围: %d + %d", a, b)
108		}
109		return a + b, nil
110	}
111	
112	// migrateState 按目标规则与对应关系转换一份完整状态。
113	//
114	// 种子、时间片、角色标识与角色排列保持不变；地点转换不要求符合旧道路。
115	// 角色所在地点与物品条目种类只按原始名称替换一次，不沿对应关系连续替换。
116	// 多个物品条目转换成同一种类时合并数量，条目位置取原列表中首次出现者，
117	// 数量为零的条目仍保留。合并数量或角色携带总量超出整数范围时返回规则
118	// 错误，不回绕也不丢弃物品。返回的状态是新建副本，入参不会被修改。
119	func migrateState(st State, target Rules, m NameMapping) (State, error) {
120		locRename := make(map[string]string, len(m.Locations))
121		for _, r := range m.Locations {
122			locRename[r.From] = r.To
123		}
124		itemRename := make(map[string]string, len(m.Items))
125		for _, r := range m.Items {
126			itemRename[r.From] = r.To
127		}
128	
129		next := State{
130			Seed:       st.Seed,
131			Rules:      cloneRules(target),
132			Time:       st.Time,
133			Characters: make([]Character, len(st.Characters)),
134		}
135		for ci, ch := range st.Characters {
136			nc := Character{ID: ch.ID, Location: ch.Location}
137			if to, ok := locRename[ch.Location]; ok {
138				nc.Location = to
139			}
140			// 按原列表次序合并到同一目标种类：首次出现的位置保留一个条目。
141			items := make([]CharacterItem, 0, len(ch.Items))
142			pos := make(map[string]int, len(ch.Items))
143			carryTotal := 0
144			for _, it := range ch.Items {
145				name := it.Item
146				if to, ok := itemRename[it.Item]; ok {
147					name = to
148				}
149				if idx, ok := pos[name]; ok {
150					sum, err := addSafe(items[idx].Count, it.Count)
151					if err != nil {
152						return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围（不回绕、不丢弃）",
153							ch.ID, name)
154					}
155					items[idx].Count = sum
156				} else {
157					pos[name] = len(items)
158					items = append(items, CharacterItem{Item: name, Count: it.Count})
159				}
160				total, err := addSafe(carryTotal, it.Count)
161				if err != nil {
162					return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
163				}
164				carryTotal = total
165			}
166			nc.Items = items
167			next.Characters[ci] = nc
168		}
169		return next, nil
170	}
171	
172	// previewMigrationLocked 在调用方已持锁（共享或排他均可）的前提下读取并
173	// 校验槽当前最新记录，校验目标规则与对应关系，计算转换后状态与阻碍。
174	func (a *Archive) previewMigrationLocked(slot string, acceptedVersions []string, target Rules, mapping NameMapping) (MigrationPreview, error) {
175		latest, err := a.readLatestLocked(slot)
176		if err != nil {
177			return MigrationPreview{}, err
178		}
179		env, err := a.loadAndVerifyLocked(latest)
180		if err != nil {
181			if ce, ok := err.(*CorruptError); ok {
182				ce.Slot = slot
183			}
184			return MigrationPreview{}, err
185		}
186		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
187			return MigrationPreview{}, &VersionRejectedError{
188				Slot:     slot,
189				Record:   latest,
190				Version:  env.State.Rules.Version,
191				Accepted: append([]string(nil), acceptedVersions...),
192			}
193		}
194		if target.Version == env.State.Rules.Version {
195			return MigrationPreview{}, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
196		}
197		if err := validateNameMapping(mapping, env.State.Rules, target); err != nil {
198			return MigrationPreview{}, err
199		}
200		converted, err := migrateState(env.State, target, mapping)
201		if err != nil {
202			return MigrationPreview{}, err
203		}
204		blockers := checkCompatibility(converted, target)
205		// 返回深拷贝，调用方修改不影响任何后续计算。
206		converted = cloneState(converted)
207		return MigrationPreview{
208			RecordID:      latest,
209			OldVersion:    env.State.Rules.Version,
210			TargetVersion: target.Version,
211			State:         converted,
212			Committable:   len(blockers) == 0,
213			Blockers:      blockers,
214		}, nil
215	}
216	
217	// PreviewMigration 预览把槽当前最新记录显式转换到目标规则后的状态。
218	//
219	// 调用方提供可接受的旧规则版本集合、合法且版本与来源不同的目标规则，以及
220	// 旧地点到新地点、旧物品到新物品的对应关系。每条对应关系的来源必须存在于
221	// 旧规则、目标必须存在于新规则（即使暂时没有角色使用也要检查）；空目标或
222	// 未知名称返回 *RuleError。未指定的名称保持原样；对应关系只作用于原始名称
223	// 一次，不连续替换，互换名称也有确定结果。角色按对应关系改变所在地点（不
224	// 要求符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种类时
225	// 合并数量并按原列表首次出现的位置保留一个条目，零数量仍保留。种子、时间
226	// 片、角色标识及角色排列保持不变。合并数量或携带总量超出整数范围时返回
227	// *RuleError，不回绕或丢弃物品。
228	//
229	// 返回来源记录标识、旧新版本、转换后的完整状态（深拷贝）及是否可提交；
230	// 转换后仍有缺失地点、不被允许的物品或超过目标携带上限时，一次列出全部
231	// 阻碍，注明角色与相关名称或数量，重复预览顺序一致。预览不改动存档，
232	// 修改返回状态也不影响来源记录。来源缺失、损坏或版本不被接受时沿用已有
233	// 的对应错误，不自动挑选历史记录。
234	func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, mapping NameMapping) (MigrationPreview, error) {
235		if !validSlotName(slot) {
236			return MigrationPreview{}, &NotFoundError{Slot: slot}
237		}
238		if err := validateRules(target); err != nil {
239			return MigrationPreview{}, err
240		}
241		lock, err := acquireSharedLock(a.dir)
242		if err != nil {
243			return MigrationPreview{}, err
244		}
245		defer lock.release()
246		preview, err := a.previewMigrationLocked(slot, acceptedVersions, target, mapping)
247		if err != nil {
248			return MigrationPreview{}, err
249		}
250		return preview, nil
251	}
252	
253	// Migrate 在预览可提交后把槽当前最新记录显式转换为目标规则并保存。
254	//
255	// 必须带预览返回的来源记录标识 expected，并重新提交目标规则与对应关系。
256	// 迁移在排他锁下重新读取来源记录并重新计算，绝不直接保存调用方可能改过
257	// 的预览状态。expected 为空或槽已更新（覆盖、升级、确认恢复或另一次迁移
258	// 抢先成功）时返回 *ConflictError；仍有阻碍时返回阻碍信息并拒绝保存。
259	// 任何拒绝都不改变当前记录或历史。
260	//
261	// 成功后产生一条以来源为父的独立新记录，保存目标规则与转换后的状态，
262	// 并加入本槽保存次序最前；旧记录及已分出的分支保留原状态，只接受旧版本
263	// 的恢复读取仍能找到迁移前记录。迁移后的记录可用 WorldFromState 继续按
264	// 新规则移动、改变物品并保存，普通读取不自动转换。写入中断后重开，只能
265	// 看到迁移前或迁移后的完整记录与历史。
266	func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, mapping NameMapping, expected RecordID) (MigrationResult, error) {
267		if !validSlotName(slot) {
268			return MigrationResult{}, &NotFoundError{Slot: slot}
269		}
270		if err := validateRules(target); err != nil {
271			return MigrationResult{}, err
272		}
273		if expected == "" {
274			return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的记录标识"}
275		}
276		lock, err := acquireLock(a.dir)
277		if err != nil {
278			return MigrationResult{}, err
279		}
280		defer lock.release()
281	
282		oldPointer, err := a.readSlotPointerLocked(slot)
283		if err != nil {
284			return MigrationResult{}, err
285		}
286		if oldPointer.Latest != expected {
287			return MigrationResult{}, &ConflictError{
288				Slot:   slot,
289				Reason: "所依据的记录已不是该槽最新记录",
290			}
291		}
292	
